modelBuilder.Entity<CommercialItemBase>().With(commItem =>
        {
            commItem.UseTpcMappingStrategy();

            commItem.UseTpcMappingStrategy()
                    .HasKey(ci => ci.InternalId);

            commItem.Property(ci => ci.InternalId)
                    .HasConversion(internalId => internalId.Value, value => InternalId.FromGuid(value));

            commItem.HasIndex(ci => new { ci.Id }).IsUnique();

            commItem.Property(ci => ci.Id)
                    .HasMaxLength(DeterministicIdMaxLength)
                    .HasConversion(id => id != null ? id.Value : null, value => value != null ? DeterministicId.FromString(value) : null);

            // Sku
            commItem.HasIndex(p => p.SkuIdentifier);

            commItem.Property(ci => ci.SkuIdentifier)
                .HasMaxLength(SkuValidation.SkuIdentifierMaxLength)
                .HasConversion(skuIdentifier => skuIdentifier.Value, value => SkuIdentifier.FromString(value));

            commItem.HasOne<SkuCategory>()
                    .WithMany()
                    .HasForeignKey(s => s.SkuCategory)
                    .IsRequired()
                    .OnDelete(DeleteBehavior.Restrict);

            commItem.Property(ci => ci.SkuCategory)
                .HasMaxLength(SkuValidation.SkuCategoryMaxLength)
                .HasConversion(skuCat => skuCat.Value, value => SkuCategoryId.FromString(value));
        })

