builder.Services.AddSingleton(sp =>
        {
            var kafkaConfiguration = sp.GetRequiredService<IOptions<KafkaProducerSettings>>().Value;
            var logger = sp.GetRequiredService<ILogger<InstrumentedProducerBuilder<Null, byte[]>>>();
            var producerConfig = new ProducerConfig
            {
                BootstrapServers = kafkaConfiguration.BootStrapServers,
                SecurityProtocol = kafkaConfiguration.SecurityProtocol,
                SaslMechanism = kafkaConfiguration.SaslMechanism,
                SaslUsername = kafkaConfiguration.SaslUserName,
                SaslPassword = kafkaConfiguration.SaslPassword,
                SocketTimeoutMs = kafkaConfiguration.SocketTimeout,
                MessageTimeoutMs = kafkaConfiguration.MessageTimeoutMs,
                TransactionTimeoutMs = kafkaConfiguration.TransactionTimeoutMs,
                ClientId = kafkaConfiguration.ClientId,
            };

            return new ProducerBuilder<Null, byte[]>(producerConfig)
                .SetErrorHandler((producer, error) => { if (error.IsFatal) { logger.LogError("Kafka Producer Error, Failed to send Message to Kafka: {Reason}, Producer:{ProducerName}", error.Reason, producer?.Name); }})
                .AsInstrumentedProducerBuilder(); 
        })

